UPDATE public.pages SET builder_data = jsonb_set(builder_data, '{sections}', (builder_data->'sections') || '{"id": "f848cf66-078c-4056-8fa8-af8d6cdd6b0e", "kind": "section", "layout": {"width": 1200, "contentWidth": "boxed"}, "children": [{"id": "8062e264-4a74-4169-b623-c7b597ef7fd2", "kind": "column", "span": {"desktop": 4}, "children": [{"id": "c67b65c9-23ca-4a68-af02-caa5fd5d1b97", "kind": "widget", "type": "icon", "content": {"name": "MessageCircle", "size": 48, "color": "#f97316", "align": "center"}}, {"id": "6091d02b-5c2f-4d83-b74d-2967558759d1", "kind": "widget", "type": "heading", "content": {"tag": "h3", "text_pl": "Wywiady", "text_en": "Interviews", "align": "center", "sizePreset": "lg"}}, {"id": "ea10ceda-b754-4dab-a3f8-92b3ac999b45", "kind": "widget", "type": "text", "content": {"html_pl": "<p style=\"text-align:center\">Dostarczają pogłębionej wiedzy poprzez rozmowy z ekspertami i decydentami. Oferują unikalne analizy i perspektywy, wzbogacając debatę publiczną oraz ułatwiając zrozumienie złożonych procesów globalnych i regionalnych.</p>", "html_en": "<p style=\"text-align:center\">They deliver in-depth knowledge through conversations with experts and decision-makers. They offer unique analyses and perspectives, enriching public debate and facilitating understanding of complex global and regional processes.</p>"}}]}, {"id": "ade666ab-4bf9-40ce-b81d-9c8aaf04e085", "kind": "column", "span": {"desktop": 4}, "children": [{"id": "ce43b532-b9e8-4d3e-87fe-14e25177a713", "kind": "widget", "type": "icon", "content": {"name": "Mic", "size": 48, "color": "#f97316", "align": "center"}}, {"id": "d2ef93c6-1ed0-4f12-920c-52f5374638e2", "kind": "widget", "type": "heading", "content": {"tag": "h3", "text_pl": "Podcast", "text_en": "Podcast", "align": "center", "sizePreset": "lg"}}, {"id": "d5ca995d-9cdc-44d3-a775-58d457ce9380", "kind": "widget", "type": "text", "content": {"html_pl": "<p style=\"text-align:center\">Podcast poprzez wywiady i analizy tematów międzynarodowych zwiększa świadomość wyzwań i trendów. Umożliwia pogłębianie wiedzy geopolitycznej, gospodarczej i społecznej, wspierając budowę zaangażowanej społeczności.</p>", "html_en": "<p style=\"text-align:center\">Through interviews and analyses of international topics, the podcast raises awareness of challenges and trends. It enables deepening of geopolitical, economic and social knowledge, supporting the building of an engaged community.</p>"}}]}, {"id": "2fb8bdb1-6735-4362-96ae-388c41ad7e04", "kind": "column", "span": {"desktop": 4}, "children": [{"id": "80135fe4-1f90-4bb8-bd20-e61864892b94", "kind": "widget", "type": "icon", "content": {"name": "GraduationCap", "size": 48, "color": "#f97316", "align": "center"}}, {"id": "5d247f97-af81-45f4-aead-2decb01d048f", "kind": "widget", "type": "heading", "content": {"tag": "h3", "text_pl": "Wykłady", "text_en": "Lectures", "align": "center", "sizePreset": "lg"}}, {"id": "dbe75486-2c29-4d7f-9dc1-e7bab9adfaf0", "kind": "widget", "type": "text", "content": {"html_pl": "<p style=\"text-align:center\">Warsztaty rozwijają praktyczne umiejętności w specjalistycznych obszarach poprzez interaktywne sesje z ekspertami. Umożliwiają pogłębianie kompetencji, pracę na realnych przypadkach i budowę sieci kontaktów między środowiskami i branżami.</p>", "html_en": "<p style=\"text-align:center\">Workshops develop practical skills in specialist areas through interactive sessions with experts. They enable deepening competences, working on real cases and building networks across communities and industries.</p>"}}]}]}'::jsonb) WHERE id = '2d7776f2-d1ad-437e-8607-62b39c2b37a2';